//! Formatter round-trip: `fmt` is stable, and the Unicode form parses to
//! the same AST as the ASCII form. Checked on every example and on random
//! programs generated by proptest.

mod common;

use graphene::fmt::{format, Style};
use graphene::parse;
use graphene::syntax::ast::*;
use proptest::prelude::*;
use rust_decimal::Decimal;

const ASCII: Style = Style { unicode: false };
const UNICODE: Style = Style { unicode: true };

/// The two round-trip properties, starting from any parsed program.
fn assert_roundtrip(prog: &Program) {
    let s1 = format(prog, ASCII);
    let (p1, d1) = parse(&s1);
    assert!(
        d1.is_empty(),
        "formatted output does not parse:\n{s1}\n{d1:#?}"
    );
    assert_eq!(format(&p1, ASCII), s1, "fmt is not stable");
    let u = format(&p1, UNICODE);
    let (pu, du) = parse(&u);
    assert!(
        du.is_empty(),
        "unicode output does not parse:\n{u}\n{du:#?}"
    );
    assert_eq!(pu, p1, "unicode form parses to a different AST:\n{u}");
    assert_eq!(format(&pu, ASCII), s1);
}

#[test]
fn examples_roundtrip() {
    for (name, path) in common::all_examples() {
        // Examples that are meant to fail parsing (a `P` code in their
        // `.expected`) have no AST to round-trip.
        let expected = path.with_extension("expected");
        if expected.exists() && common::read(&expected).starts_with('P') {
            continue;
        }
        let (prog, diags) = parse(&common::read(&path));
        assert!(diags.is_empty(), "{name}: {diags:#?}");
        assert_roundtrip(&prog);
    }
}

#[test]
fn canonical_example_is_already_formatted() {
    let path = common::root().join("examples/learn/order_total.grph");
    let src = common::read(&path);
    let (prog, _) = parse(&src);
    assert_eq!(format(&prog, ASCII), src);
}

// ---------------------------------------------------------------------
// Random program generation (v0.4 constructs included)
// ---------------------------------------------------------------------

fn id(name: &str) -> Ident {
    Ident {
        name: name.to_string(),
        pos: Pos::default(),
    }
}

fn ident() -> impl Strategy<Value = Ident> {
    prop::sample::select(vec![
        "A", "B", "C1", "x", "usr_id", "total", "indep", "_t", "N9",
    ])
    .prop_map(id)
}

/// A record field name: an identifier or, since v0.4, a keyword (D-063).
fn field_name() -> impl Strategy<Value = Ident> {
    prop_oneof![
        ident(),
        prop::sample::select(vec!["f", "in", "out", "match", "err", "true", "sink"]).prop_map(id),
    ]
}

fn lit() -> impl Strategy<Value = Lit> {
    prop_oneof![
        any::<u64>().prop_map(Lit::Int),
        (0i64..1_000_000_000, 1u32..5).prop_map(|(m, s)| Lit::Dec(Decimal::new(m, s))),
        "[^\r\n]{0,8}".prop_map(Lit::Str),
        any::<bool>().prop_map(Lit::Bool),
    ]
}

fn ex(kind: ExprKind) -> Expr {
    Expr {
        kind,
        pos: Pos::default(),
    }
}

fn bin_op() -> impl Strategy<Value = BinOp> {
    use BinOp::*;
    prop::sample::select(vec![
        Or, And, Eq, Ne, Lt, Le, Gt, Ge, Add, Sub, Mul, Div, Rem, Concat,
    ])
}

fn expr() -> impl Strategy<Value = Expr> {
    let leaf = prop_oneof![
        lit().prop_map(|l| ex(ExprKind::Lit(l))),
        ident().prop_map(|i| ex(ExprKind::Name(i))),
    ];
    leaf.prop_recursive(4, 24, 2, |inner| {
        prop_oneof![
            (inner.clone(), field_name()).prop_map(|(e, f)| ex(ExprKind::Field(Box::new(e), f))),
            (any::<bool>(), inner.clone()).prop_map(|(not, e)| {
                let op = if not { UnOp::Not } else { UnOp::Neg };
                ex(ExprKind::Unary(op, Box::new(e)))
            }),
            (bin_op(), inner.clone(), inner.clone()).prop_map(|(op, l, r)| ex(ExprKind::Binary(
                op,
                Box::new(l),
                Box::new(r)
            ))),
            prop::collection::vec((field_name(), inner.clone()), 1..3)
                .prop_map(|fs| ex(ExprKind::Record(fs))),
            (
                prop::sample::select(vec![NumTy::U64, NumTy::I64, NumTy::Dec]),
                inner.clone()
            )
                .prop_map(|(t, e)| ex(ExprKind::Convert(t, Box::new(e)))),
            prop::collection::vec(inner.clone(), 0..3).prop_map(|xs| ex(ExprKind::List(xs))),
            (inner.clone(), inner.clone(), inner.clone()).prop_map(|(c, a, b)| ex(ExprKind::If(
                Box::new(c),
                Box::new(a),
                Box::new(b)
            ))),
            (inner.clone(), inner.clone())
                .prop_map(|(b, i)| ex(ExprKind::Index(Box::new(b), Box::new(i)))),
            (
                prop::sample::select(Builtin::ALL.to_vec()),
                prop::collection::vec(inner, 1..3)
            )
                .prop_map(|(b, xs)| ex(ExprKind::Builtin(b, xs))),
        ]
    })
}

fn ty() -> impl Strategy<Value = Ty> {
    let scalar = prop::sample::select(vec![
        TyKind::U64,
        TyKind::I64,
        TyKind::Dec,
        TyKind::Bool,
        TyKind::Str,
        TyKind::Date,
        TyKind::Named("Region".into()),
        TyKind::Named("total".into()),
    ])
    .prop_map(|kind| Ty {
        kind,
        pos: Pos::default(),
    });
    let scaled = (0u32..=28).prop_map(|n| Ty {
        kind: TyKind::DecScale(n),
        pos: Pos::default(),
    });
    prop_oneof![scalar, scaled].prop_recursive(2, 8, 3, |inner| {
        prop_oneof![
            prop::collection::vec((field_name(), inner.clone()), 1..3).prop_map(|fs| Ty {
                kind: TyKind::Record(
                    fs.into_iter()
                        .map(|(name, ty)| Field { name, ty })
                        .collect(),
                ),
                pos: Pos::default(),
            }),
            inner.prop_map(|t| Ty {
                kind: TyKind::List(Box::new(t)),
                pos: Pos::default(),
            }),
        ]
    })
}

fn args() -> impl Strategy<Value = Vec<Arg>> {
    prop::collection::vec(
        (ident(), expr(), any::<bool>()).prop_map(|(name, value, each)| Arg { name, value, each }),
        0..3,
    )
}

fn op() -> impl Strategy<Value = Op> {
    prop_oneof![
        expr().prop_map(Op::Pure),
        (ident(), args()).prop_map(|(effect, args)| Op::Fx { effect, args }),
        (ident(), args()).prop_map(|(effect, args)| Op::FxAsync { effect, args }),
        (
            prop::sample::select(vec![CallKind::Call, CallKind::Map, CallKind::Filter]),
            ident(),
            args()
        )
            .prop_map(|(kind, graph, args)| Op::Call { kind, graph, args }),
    ]
}

fn flow() -> impl Strategy<Value = Stmt> {
    let sources = prop_oneof![
        ident().prop_map(|i| vec![i]),
        prop::collection::vec(ident(), 2..4),
    ];
    let target = prop_oneof![
        (ident(), prop::option::of(ty())).prop_map(|(name, ty)| Target::Node { name, ty }),
        ident().prop_map(Target::Sink),
    ];
    let errs = prop::collection::vec(
        (prop::option::of(ident()), ident())
            .prop_map(|(variant, target)| ErrEdge { variant, target }),
        0..3,
    );
    (sources, op(), target, errs).prop_map(|(sources, op, target, errs)| {
        Stmt::Flow(Flow {
            sources,
            op,
            target,
            errs,
            pos: Pos::default(),
        })
    })
}

fn arm() -> impl Strategy<Value = Arm> {
    let pat = prop_oneof![
        lit().prop_map(|l| Pat::Lit(l, Pos::default())),
        Just(Pat::Wild(Pos::default())),
        ident().prop_map(Pat::Variant),
    ];
    (pat, ident()).prop_map(|(pat, target)| Arm { pat, target })
}

fn stmt() -> impl Strategy<Value = Stmt> {
    let p = Pos::default;
    prop_oneof![
        "[^\r\n]{0,10}".prop_map(move |s| Stmt::Intent(s, p())),
        (
            any::<bool>(),
            ident(),
            prop::collection::vec((ident(), ty()), 0..3),
            prop::option::of(ty()),
            prop::collection::vec(ident(), 0..3)
        )
            .prop_map(
                move |(is_async, name, ps, ret, errors)| Stmt::Extern(Extern {
                    is_async,
                    name,
                    ret,
                    errors,
                    pos: p(),
                    params: ps
                        .into_iter()
                        .map(|(name, ty)| Field { name, ty })
                        .collect(),
                })
            ),
        (ident(), ty(), prop::option::of(ident())).prop_map(move |(name, ty, node)| Stmt::Input(
            Input {
                name,
                ty,
                node,
                pos: p()
            }
        )),
        flow(),
        (ident(), expr(), prop::collection::vec(arm(), 1..4)).prop_map(
            move |(source, scrutinee, arms)| {
                Stmt::Match(MatchStmt {
                    source,
                    scrutinee,
                    arms,
                    pos: p(),
                })
            }
        ),
        (ident(), ident(), ty()).prop_map(move |(source, name, ty)| Stmt::Out(OutStmt {
            source,
            name: Some(name),
            ty: Some(ty),
            pos: p()
        })),
        ident().prop_map(move |source| Stmt::Out(OutStmt {
            source,
            name: None,
            ty: None,
            pos: p()
        })),
        (ident(), ty(), expr()).prop_map(move |(name, ty, value)| Stmt::Const(ConstDecl {
            name,
            ty,
            value,
            pos: p()
        })),
        (
            ident(),
            prop::collection::vec((ident(), ty(), prop::option::of(ident())), 0..3),
            ty(),
            prop::collection::vec(ident(), 0..3)
        )
            .prop_map(
                move |(name, ps, ret, errors)| Stmt::GraphHeader(GraphHeader {
                    name,
                    params: ps
                        .into_iter()
                        .map(|(name, ty, node)| Input {
                            name,
                            ty,
                            node,
                            pos: p()
                        })
                        .collect(),
                    ret,
                    errors,
                    pos: p(),
                })
            ),
        Just(Stmt::GraphEnd(p())),
        (ident(), prop::option::of(ident())).prop_map(move |(source, name)| Stmt::Fail(FailStmt {
            source,
            name,
            pos: p()
        })),
        Just(Stmt::AssertTotal(p())),
        ident().prop_map(move |s| Stmt::AssertIndep(s, p())),
        "[a-z/._]{0,12}".prop_map(move |path| Stmt::Import(Import { path, pos: p() })),
        (ident(), ty()).prop_map(move |(name, ty)| Stmt::TypeAlias(TypeAlias {
            name,
            ty,
            pos: p()
        })),
        (ident(), prop::collection::vec(ident(), 1..4)).prop_map(move |(name, variants)| {
            Stmt::Enum(EnumDecl {
                name,
                variants,
                pos: p(),
            })
        }),
    ]
}

fn program() -> impl Strategy<Value = Program> {
    let line =
        (prop::option::of(stmt()), prop::option::of("[ -~]{0,10}")).prop_map(|(stmt, comment)| {
            Line {
                stmt,
                comment,
                at: LineSpan::default(),
            }
        });
    // v0.4 is a superset of older versions, so 0.4 programs cover every
    // construct.
    prop::collection::vec(line, 0..12).prop_map(|lines| Program {
        version: (0, 4),
        lines,
    })
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(256))]
    #[test]
    fn random_programs_roundtrip(prog in program()) {
        assert_roundtrip(&prog);
    }
}
// Covers v0.4.
